<?php
// Run on EACH client server. Creates private configuration and public manifest only.
$options=getopt('',['central:','company:','private-dir:','webroot:']);
if(empty($options['central'])||empty($options['company'])||empty($options['private-dir'])||empty($options['webroot'])){echo "Usage: php setup-connector.php --central=https://central.example/api --company=1 --private-dir=/private/support --webroot=/path/to/erp\n";exit(1);}
$central=rtrim($options['central'],'/');if(parse_url($central,PHP_URL_SCHEME)!=='https'||!filter_var($central,FILTER_VALIDATE_URL)||parse_url($central,PHP_URL_USER)||parse_url($central,PHP_URL_PASS)||parse_url($central,PHP_URL_QUERY)||parse_url($central,PHP_URL_FRAGMENT))throw new RuntimeException('Use an HTTPS central API URL without credentials or query');
if(!function_exists('openssl_pkey_new'))throw new RuntimeException('Enable PHP OpenSSL');$dir=$options['private-dir'];if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Cannot create private directory');$dir=realpath($dir);$web=realpath($options['webroot']);if(!$web)throw new RuntimeException('ERP webroot not found');if($web&&strpos(strtolower(str_replace('\\','/',$dir)).'/',strtolower(str_replace('\\','/',realpath($web))).'/')===0)throw new RuntimeException('Private config must be outside webroot');
$file=$dir.'/support-client.php';if(is_file($file))throw new RuntimeException('Configuration already exists; refusing to rotate keys silently');$pair=openssl_pkey_new(['private_key_type'=>OPENSSL_KEYTYPE_RSA,'private_key_bits'=>2048,'config'=>__DIR__.'/openssl.cnf']);if(!$pair||!openssl_pkey_export($pair,$private,null,['config'=>__DIR__.'/openssl.cnf']))throw new RuntimeException('Key generation failed');$bytes=random_bytes(16);$bytes[6]=chr((ord($bytes[6])&15)|64);$bytes[8]=chr((ord($bytes[8])&63)|128);$hex=bin2hex($bytes);$uuid=substr($hex,0,8).'-'.substr($hex,8,4).'-'.substr($hex,12,4).'-'.substr($hex,16,4).'-'.substr($hex,20);$public=base64_encode(openssl_pkey_get_details($pair)['key']);
$cfg=['uuid'=>$uuid,'central_api'=>$central,'company'=>(string)$options['company'],'key_id'=>'initial','private_key_base64'=>base64_encode($private)];file_put_contents($file,'<?php return '.var_export($cfg,true).';',LOCK_EX);chmod($file,0600);
$manifest=['uuid'=>$uuid,'company'=>(string)$options['company'],'key_id'=>'initial','public_key'=>$public];file_put_contents($dir.'/public-registration.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo "Private configuration created. Register ONLY public-registration.json in the central support UI.\nSet SUPPORT_CONNECTOR_CONFIG to the private support-client.php path. Never upload that file to webroot.\n";
